(function(root){
'use strict';
const known=new Set(['ai','tips','devices','safety']);
function topicImage(id,p=''){return p+'assets/'+(known.has(id)?'topic-'+id+'.webp':'network.svg');}
function topics(data,C){const E=C.escape;return `<section class="container section topic-atlas" id="kham-pha"><div class="section-heading"><div><span class="eyebrow">BẢN ĐỒ KHÁM PHÁ</span><h2>Mỗi điều tò mò.<br><span>Một hướng để bắt đầu.</span></h2></div><p>Chọn một chủ đề gần bạn.<br>Đi từ câu hỏi nhỏ tới điều có thể áp dụng.</p></div><div class="topic-atlas-grid">${data.categories.map((c,i)=>`<a class="topic-cover-card" href="chuyen-muc/${c.id}.html"><div class="topic-cover-image"><img src="${topicImage(c.id)}" width="960" height="540" alt="" loading="lazy"><span aria-hidden="true">0${i+1}</span></div><div class="topic-cover-copy"><small>${data.articles.filter(a=>a.category===c.id).length} CẨM NANG</small><h3>${E(c.name)} <span aria-hidden="true">↗</span></h3><p>${E(c.description)}</p></div></a>`).join('')}</div></section>`;}
function categoryIntro(category,data,C,p='../'){
 const E=C.escape,list=data.articles.filter(a=>a.category===category.id),first=list.find(a=>a.featured)||[...list].sort((a,b)=>a.minutes-b.minutes||a.id.localeCompare(b.id))[0],terms=(data.glossary||[]).filter(t=>t.category===category.id);
 return `<section class="topic-page-hero"><div class="topic-page-copy"><a class="topic-back" href="${p}index.html#kham-pha">← Bản đồ khám phá</a><span class="eyebrow">CHUYÊN MỤC / ${E(category.short||category.name)}</span><h1>${E(category.name)}.<br><span>Hiểu từ điều gần bạn.</span></h1><p>${E(category.description)}</p><div class="topic-page-count"><span>${list.length} cẩm nang</span><span>${terms.length} thuật ngữ</span></div><a class="button button-outline" href="#category-page-grid">Chọn bài bạn muốn đọc ↓</a></div><div class="topic-page-art"><img src="${topicImage(category.id,p)}" width="960" height="540" alt="" fetchpriority="high"><span>MINH HỌA CHUYÊN MỤC / TECH HORIZON</span></div></section>${first?`<aside class="topic-first-read"><span class="eyebrow">MỘT ĐIỂM BẮT ĐẦU · ${first.minutes} PHÚT</span><div><h2><a href="${p}bai-viet/${first.id}.html">${E(first.title)}</a></h2><p>${E(first.takeaway)}</p></div><a class="text-button" href="${p}bai-viet/${first.id}.html">Đọc từ đây ↗</a></aside>`:''}`;
}
function sources(article,data,C){
 const E=C.escape;return `<section class="article-sources source-panel" id="nguon-tham-khao"><div class="source-panel-heading"><div><span class="eyebrow">ĐỌC THÊM TỪ GỐC</span><h2>Nguồn để đối chiếu.</h2></div><span>${article.sources.length} liên kết</span></div><p class="source-panel-intro">Mở tài liệu gốc, xem phạm vi và thời điểm cập nhật trước khi áp dụng.</p>${article.sources.length?`<ol class="source-link-list">${article.sources.map((source,i)=>{const url=C.url(source.url);return `<li><a href="${E(url)}" target="_blank" rel="noopener noreferrer"><span class="source-number">${String(i+1).padStart(2,'0')}</span><span><strong>${E(source.label)}</strong><small>${E(new URL(url).hostname.replace(/^www\./,''))}</small></span><b aria-hidden="true">↗</b></a></li>`;}).join('')}</ol>`:'<p class="source-panel-empty">Bài này chưa có nguồn đọc thêm. Chủ kênh có thể bổ sung trong Bàn biên tập.</p>'}<div class="source-panel-bottom"><p>Danh sách do chủ kênh biên tập, chưa được website tự xác minh.</p><button type="button" class="text-button" data-download-reading="${article.id}" hidden>Tải bản đọc TXT ↗</button></div></section>`;
}
function readingText(article,data,C){const origin=(C.url(data.config.siteUrl)||'').replace(/\/$/,'');return data.config.name+'\n'+article.title+'\n'+(origin?origin+'/':'')+'bai-viet/'+article.id+'.html\n\nĐIỀU NÊN NHỚ\n'+article.takeaway+'\n\n'+article.sections.map((s,i)=>(i+1)+'. '+s.heading+'\n'+s.text).join('\n\n')+'\n\nNGUỒN ĐỌC THÊM\n'+article.sources.map(s=>'- '+s.label+'\n  '+C.url(s.url)).join('\n')+'\n\n'+(data.config.contentNote||'')+'\n';}
function terms(data,C,urlFor){const E=C.escape;return (data.glossary||[]).map(t=>{
 const related=data.articles.filter(a=>a.category===t.category).slice(0,2),url=a=>urlFor?urlFor(a):'bai-viet/'+a.id+'.html';
 return `<article class="term-card" id="${E(t.id)}" data-term="${E(t.id)}"><a class="term-category" href="thuat-ngu.html?category=${E(t.category||'all')}">${E(data.categories.find(c=>c.id===t.category)?.short||'Công nghệ')}</a><h2><a href="#${E(t.id)}" aria-label="Liên kết tới thuật ngữ ${E(t.term)}">${E(t.term)}<span aria-hidden="true">#</span></a></h2><p>${E(t.definition)}</p>${C.url(t.url)?`<a class="term-source" href="${E(C.url(t.url))}" target="_blank" rel="noopener noreferrer">Đọc thêm từ nguồn ↗</a>`:'<small>Chưa có nguồn đọc thêm.</small>'}${related.length?`<details class="term-related"><summary>Đọc trong một tình huống</summary><div>${related.map(a=>`<a href="${E(url(a))}">${E(a.title)} <span>↗</span></a>`).join('')}</div></details>`:''}</article>`;
 }).join('');}
function journeyCard(j,index,data,C,p='',urlFor){const E=C.escape,list=j.articles.map(id=>data.articles.find(a=>a.id===id)).filter(Boolean),url=a=>urlFor?urlFor(a):p+'bai-viet/'+a.id+'.html';return `<article class="journey-card journey-${E(j.category||'ai')}" id="${E(j.id)}"><div class="journey-heading"><span class="journey-no">${String(index+1).padStart(2,'0')}</span><span class="tag">${list.length} cẩm nang · ${list.reduce((n,a)=>n+a.minutes,0)} phút</span></div><h3>${E(j.title)}</h3><p>${E(j.description)}</p><div class="journey-progress" data-journey-progress="${E(j.id)}"><span style="width:0%"></span></div><span class="journey-progress-text" data-journey-text="${E(j.id)}">Chưa bắt đầu trên thiết bị này</span><ol>${list.map((a,i)=>`<li><a href="${E(url(a))}" data-journey-article="${a.id}"><span>${String(i+1).padStart(2,'0')}</span><strong>${E(a.title)}</strong><span aria-hidden="true">↗</span></a></li>`).join('')}</ol>${list.length?`<a class="text-button" href="${E(url(list[0]))}" data-journey-start="${E(j.id)}">Bắt đầu lộ trình ↗</a>`:''}</article>`;}
function pageGroups(data){return [
 {id:'read',label:'01 / KHÁM PHÁ & ĐỌC',title:'Điều bạn muốn hiểu.',text:'Tìm một bài, theo một lộ trình hoặc giải nghĩa một thuật ngữ.',items:[
 ['tat-ca.html','Cẩm nang công nghệ',data.articles.length+' bài theo từng tình huống','Nội dung công khai'],
 ['chuyen-de.html','Lộ trình đọc',(data.journeys||[]).length+' mạch kiến thức, đi từng bước','Tiến độ trên thiết bị'],
 ['thuat-ngu.html','Từ điển công nghệ',(data.glossary||[]).length+' định nghĩa có đường dẫn đọc thêm','Tra cứu nhanh'],
 ['thu-vien.html','Thư viện cá nhân','Bài đã lưu, ghi chú và phần đang đọc dở','Dữ liệu trên thiết bị']]},
 {id:'do',label:'02 / THỬ & ỨNG DỤNG',title:'Điều bạn có thể làm.',text:'Đọc có mục tiêu, thử bằng công cụ rồi giữ lại kết quả.',items:[
 ['thuc-hanh.html','Trạm thực hành','Phiếu có bài đọc, hướng dẫn và phần tự đối chiếu','Phiếu trên thiết bị'],
 ['studio.html','Studio công nghệ','Prompt, tải tệp, UTM, rà soát, ảnh và kịch bản','Xử lý trên trình duyệt']]},
 {id:'create',label:'03 / GÓC LÀM NỘI DUNG',title:'Từ ý tưởng tới bài viết.',text:'Một quy trình cho chủ kênh, từ kế hoạch tới bộ website hoàn chỉnh.',items:[
 ['dieu-hanh.html','Kế hoạch nội dung','Bảng tiến độ, lịch tháng, dàn ý và xuất lịch','Kế hoạch trên thiết bị'],
 ['bien-tap.html','Bàn biên tập','Sửa kênh, cẩm nang, lộ trình và thuật ngữ; xuất ZIP','Bản nháp trên thiết bị'],
 ['du-lieu.html','Dữ liệu & hiển thị','Sao lưu, khôi phục và điều chỉnh trải nghiệm đọc','Bạn chủ động sao lưu']]},
 {id:'help',label:'04 / THÔNG TIN & HỖ TRỢ',title:'Biết rõ trước khi dùng.',text:'Hiểu về kênh, cách vận hành và phạm vi lưu dữ liệu.',items:[
 ['gioi-thieu.html','Giới thiệu & hợp tác','Hồ sơ kênh và mẫu đề xuất để bạn tự gửi','Thông tin công khai'],
 ['huong-dan.html','Hướng dẫn sử dụng','Bắt đầu, xử lý vướng mắc và xuất bản từng bước','Hướng dẫn vận hành'],
 ['chinh-sach.html','Quyền riêng tư','Dữ liệu trên thiết bị, biểu mẫu và liên kết ngoài','Phạm vi rõ ràng']]}];}
function pageInfo(file,data){
 if(file.startsWith('bai-viet/')){const a=data.articles.find(a=>'bai-viet/'+a.id+'.html'===file);return a?{label:a.title,group:'read',category:data.categories.find(c=>c.id===a.category)}:null;}
 if(file.startsWith('chuyen-muc/')){const c=data.categories.find(c=>'chuyen-muc/'+c.id+'.html'===file);return c?{label:c.name,group:'read'}:null;}
 for(const group of pageGroups(data)){const item=group.items.find(i=>i[0]===file);if(item)return {label:item[1],group:group.id};}
 return file==='ban-do.html'?{label:'Toàn bộ website',group:'help'}:file==='404.html'?{label:'Không tìm thấy trang',group:'help'}:null;
}
function pageChrome(file,data,C,prefix){
 const info=pageInfo(file,data);if(!info)return '';const E=C.escape,p=prefix??(file.includes('/')?'../':''),group=pageGroups(data).find(g=>g.id===info.group);
 const crumbs=[['index.html','Trang chủ'],['ban-do.html','Toàn bộ website']];if(info.category)crumbs.push(['chuyen-muc/'+info.category.id+'.html',info.category.name]);
 const nav=file.startsWith('bai-viet/')?'':`<nav class="section-rail" aria-label="Các trang trong khu này"><span>${E(group.label.slice(5))}</span>${group.items.map(([path,label])=>`<a href="${p+path}"${path===file?' aria-current="page"':''}>${E(label)}</a>`).join('')}<a class="section-rail-all" href="${p}ban-do.html">Mọi không gian ↗</a></nav>`;
 return `<div class="container page-context"><nav class="site-crumbs" aria-label="Vị trí trang"><ol>${crumbs.map(([path,label])=>`<li><a href="${p+path}">${E(label)}</a></li>`).join('')}<li aria-current="page">${E(info.label)}</li></ol></nav>${nav}</div>`;
}
function directory(data,C){const E=C.escape;return `<div class="directory-intro"><span class="eyebrow">TECH HORIZON / MỌI KHÔNG GIAN</span><h1>Đi đúng nơi.<br><span>Làm điều bạn cần.</span></h1><p>Từ cẩm nang đầu tiên tới góc làm nội dung của riêng bạn. Mọi phần của Tech Horizon, kết nối trên một bản đồ.</p><nav aria-label="Chọn khu trên bản đồ">${pageGroups(data).map(g=>`<a href="#khu-${g.id}">${E(g.title)} ↓</a>`).join('')}</nav></div><div class="directory-groups">${pageGroups(data).map(g=>`<section id="khu-${g.id}" class="directory-group directory-${g.id}"><div class="directory-group-heading"><span class="eyebrow">${E(g.label)}</span><h2>${E(g.title)}</h2><p>${E(g.text)}</p></div><div class="directory-links">${g.items.map(([path,title,text,label],i)=>`<a href="${path}"><span class="directory-link-no">${String(i+1).padStart(2,'0')}</span><div><small>${E(label)}</small><h3>${E(title)}</h3><p>${E(text)}</p></div><b aria-hidden="true">↗</b></a>`).join('')}</div></section>`).join('')}</div>`;}
function homePaths(C){return `<section class="container home-paths" aria-labelledby="home-paths-title"><div><span class="eyebrow">BẠN MUỐN LÀM GÌ HÔM NAY?</span><h2 id="home-paths-title">Một điểm đến cho mỗi nhu cầu.</h2></div><nav aria-label="Lối vào các khu"><a href="tat-ca.html"><small>ĐỌC & HIỂU</small><strong>Tìm một cẩm nang <span>↗</span></strong></a><a href="thuc-hanh.html"><small>THỬ & ÁP DỤNG</small><strong>Làm một việc nhỏ <span>↗</span></strong></a><a href="ban-do.html"><small>TOÀN BỘ WEBSITE</small><strong>Xem mọi không gian <span>↗</span></strong></a></nav></section>`;}
function nextSteps(file,data,C){
 if(file==='index.html'||file.startsWith('bai-viet/')||file==='doc-bai.html')return '';
 const E=C.escape,p=file.includes('/')?'../':'',owner=['dieu-hanh.html','bien-tap.html','du-lieu.html','huong-dan.html'].includes(file);
 const routes=owner?[['dieu-hanh.html','01 / LÊN Ý TƯỞNG','Giữ nhịp nội dung'],['bien-tap.html','02 / BIÊN TẬP','Chuẩn bị bản website'],['du-lieu.html','03 / GIỮ BẢN SAO','Sao lưu công sức']]:[['chuyen-de.html','ĐỌC THEO MỘT MẠCH','Chọn lộ trình tiếp theo'],['thuc-hanh.html','TỪ HIỂU ĐẾN LÀM','Thử một nhiệm vụ'],['thu-vien.html','GÓC ĐỌC CÁ NHÂN','Quay về điều đã lưu']];
 const choices=routes.filter(([path])=>path!==file).slice(0,2);
 return `<section class="container page-next" aria-label="Bước tiếp theo"><div><span class="eyebrow">TIẾP TỤC TỪ ĐÂY</span><h2>Đã tìm được điều bạn cần?</h2><a href="${p}ban-do.html">Xem toàn bộ website ↗</a></div>${choices.map(([path,tag,title])=>`<a href="${p+path}"><small>${tag}</small><strong>${title}<span aria-hidden="true">↗</span></strong></a>`).join('')}</section>`;
}
function glossaryEntries(data,C,options={}){const query=C.normalize(options.query||'');return (data.glossary||[]).filter(t=>(!options.category||options.category==='all'||t.category===options.category)&&C.normalize(t.term+' '+t.definition).includes(query)).sort(options.sort==='az'?(a,b)=>a.term.localeCompare(b.term,'vi'):()=>0);}
function journeyEntries(data,C,options={},progress={}){const query=C.normalize(options.query||'');return (data.journeys||[]).map(j=>{const list=j.articles.map(id=>data.articles.find(a=>a.id===id)).filter(Boolean),done=list.filter(a=>(progress[a.id]?.percent||0)>=95).length;return {journey:j,minutes:list.reduce((n,a)=>n+a.minutes,0),done,total:list.length,started:list.some(a=>(progress[a.id]?.percent||0)>0)};}).filter(({journey:j,minutes,done,total,started})=>(!options.category||options.category==='all'||j.category===options.category)&&(!options.minutes||Number(options.minutes)===0||minutes<=Number(options.minutes))&&C.normalize(j.title+' '+j.description).includes(query)&&(options.state!=='new'||!started)&&(options.state!=='active'||started&&done<total)&&(options.state!=='done'||done===total));}
const api={topics,categoryIntro,sources,readingText,topicImage,terms,journeyCard,pageGroups,pageInfo,pageChrome,directory,homePaths,nextSteps,glossaryEntries,journeyEntries};if(typeof module==='object'&&module.exports)module.exports=api;else root.THEditorial=api;
})(typeof window!=='undefined'?window:globalThis);
